  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 The Renaissance: Rebirth of Learning and Art$j$, $j${"readings": [{"title": "Psalm 139 (King James Version)", "url": "/portal/bible/Psalms/139"}], "body": "Renaissance means rebirth. Beginning in Italy in the 1300s, many people took fresh interest in the learning of Greece and Rome and in the dignity of the human person. Why Italy? Its cities, such as Florence, Venice and Genoa, were rich from trade. Wealthy families such as the Medici of Florence paid artists and scholars. Italy also held the ruins and books of ancient Rome, and Greek scholars arrived after Constantinople fell in 1453.\n\nThe key idea was humanism, the study of literature, history and human achievement, while still honoring God. Petrarch is called the father of humanism. Machiavelli wrote The Prince about gaining and keeping power. Artists used perspective and studied anatomy. Leonardo da Vinci painted the Mona Lisa and The Last Supper and made notebooks of inventions. Michelangelo painted the Sistine Chapel ceiling and carved David. Raphael painted The School of Athens.\n\nAround 1455 Johannes Gutenberg printed the Bible with movable type in Germany. Printing made books cheaper, spread ideas fast and raised literacy.\n\nThe Renaissance moved north. Erasmus called for Bible study and Church reform, Thomas More wrote Utopia, and William Shakespeare wrote plays in England. Psalm 139:14 says, I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.\n\nYour task: (1) Give two reasons the Renaissance began in Italy. (2) Define humanism. (3) Explain two effects of the printing press.\n\nFlorida standards: SS.912.W.4.1, SS.912.W.4.2, SS.912.W.4.3, SS.912.W.4.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.4.1, SS.912.W.4.2, SS.912.W.4.3, SS.912.W.4.4", "script": "Welcome to Unit 5. Listen, the word Renaissance means rebirth. Beginning in Italy in the thirteen hundreds, many people took fresh interest in the learning of Greece and Rome and in the dignity of the human person. Why Italy? Its cities, such as Florence, Venice and Genoa, were rich from trade. Wealthy families like the Medici of Florence paid artists and scholars. Italy held the ruins and books of ancient Rome, and Greek scholars arrived after Constantinople fell in fourteen fifty three.\n\nNow watch this. The key idea was humanism, the study of literature, history and human achievement, while still honoring God. Petrarch is called the father of humanism. Machiavelli wrote The Prince about gaining and keeping power. Artists used perspective and studied anatomy. Leonardo da Vinci painted the Mona Lisa and The Last Supper. Michelangelo painted the Sistine Chapel ceiling and carved David. Raphael painted The School of Athens.\n\nLook at this. Around fourteen fifty five Johannes Gutenberg printed the Bible with movable type. Printing made books cheaper, spread ideas fast and raised literacy. And the Renaissance moved north. Erasmus called for Bible study and reform, Thomas More wrote Utopia, and William Shakespeare wrote his plays in England. Psalm one thirty nine and fourteen says, I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.\n\nYour task today. Give two reasons the Renaissance began in Italy. Define humanism. And explain two effects of the printing press. Take the four question check.\n\nHuman gifts come from the Giver. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 The Renaissance: Rebirth of Learning and Art$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 The Protestant and Catholic Reformations$j$, $j${"readings": [{"title": "Ephesians 2 (King James Version)", "url": "/portal/bible/Ephesians/2"}], "body": "By 1500 many Christians believed the Church needed reform. Problems included the selling of indulgences, worldly clergy and little access to the Bible in common language. On October 31, 1517, Martin Luther, a monk and professor in Wittenberg, Germany, posted Ninety Five Theses against indulgences. Luther taught that salvation is by faith in Christ alone and that the Bible is the final authority. Ephesians 2:8 and 9 says, For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: Not of works, lest any man should boast. The Diet of Worms in 1521 ordered him to recant, but he refused to act against conscience. He translated the New Testament into German.\n\nThe Reformation spread. John Calvin taught in Geneva about the sovereignty of God. Ulrich Zwingli led reform in Zurich. In England, Henry VIII broke with Rome in the Act of Supremacy of 1534, partly because he wanted an annulment, and the Church of England formed. William Tyndale translated the English Bible and was executed. In 1611 the King James Version was published.\n\nThe Catholic Church responded with the Catholic or Counter Reformation. The Council of Trent from 1545 to 1563 restated doctrine and reformed abuses. Ignatius of Loyola founded the Jesuits in 1540 to educate and send out missionaries. Wars of religion followed, and the Peace of Augsburg in 1555 let German princes choose Lutheranism or Catholicism for their lands.\n\nYour task: (1) Tell what Luther did in 1517 and why. (2) Name two Reformers and one belief of each. (3) Explain two parts of the Catholic Reformation.\n\nFlorida standards: SS.912.W.4.7, SS.912.W.4.8, SS.912.W.4.9.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.4.7, SS.912.W.4.8, SS.912.W.4.9", "script": "Welcome back. Listen, by fifteen hundred many Christians believed the Church needed reform. They pointed to the selling of indulgences, worldly clergy and little access to the Bible in the common language. On October thirty first, fifteen seventeen, Martin Luther, a monk and professor in Wittenberg, Germany, posted ninety five theses against indulgences. He taught that salvation is by faith in Christ alone and that the Bible is the final authority. Ephesians two, verses eight and nine, says, For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: Not of works, lest any man should boast. At the Diet of Worms in fifteen twenty one he was ordered to recant, but he would not act against conscience. He translated the New Testament into German.\n\nNow watch this. The Reformation spread. John Calvin taught in Geneva about the sovereignty of God. Ulrich Zwingli led reform in Zurich. In England Henry the Eighth broke with Rome in the Act of Supremacy of fifteen thirty four, partly because he wanted an annulment, and the Church of England formed. William Tyndale translated the Bible into English and was put to death. In sixteen eleven the King James Version was published.\n\nLook at this. The Catholic Church answered with the Catholic Reformation. The Council of Trent, fifteen forty five to fifteen sixty three, restated doctrine and corrected abuses. Ignatius of Loyola founded the Jesuits in fifteen forty to educate and send out missionaries. Wars of religion followed, and the Peace of Augsburg in fifteen fifty five let German princes choose Lutheranism or Catholicism for their lands.\n\nYour task today. Tell what Luther did and why. Name two Reformers and one belief of each. And explain two parts of the Catholic Reformation. Take the four question check.\n\nThe Word of God is living and powerful. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 The Protestant and Catholic Reformations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 The Scientific Revolution$j$, $j${"readings": [{"title": "Psalm 111 (King James Version)", "url": "/portal/bible/Psalms/111"}], "body": "In the 1500s and 1600s, thinkers began to study nature with careful observation, measurement and experiment. This is the Scientific Revolution. Many early scientists were devout believers who saw their work as studying God's creation. Psalm 111:2 says, The works of the LORD are great, sought out of all them that have pleasure therein.\n\nKey figures:\nNicolaus Copernicus proposed in 1543 that the Earth and planets orbit the sun.\nTycho Brahe made precise observations of the stars, and Johannes Kepler used them to show that planets move in ellipses.\nGalileo Galilei used the telescope to see moons around Jupiter and mountains on the moon. He defended the sun centered model, and in 1633 the Church court condemned him.\nFrancis Bacon urged the method of experiment and observation. Rene Descartes stressed reasoning and doubt.\nAndreas Vesalius studied the human body, and William Harvey described the circulation of blood.\nIsaac Newton described gravity and the laws of motion in 1687.\n\nWhy did this happen? The Renaissance brought a new curiosity, printing spread findings, better instruments such as the telescope and microscope appeared, and explorers brought new knowledge. The effects included the scientific method, new inventions and a growing belief that reason and evidence can explain the world. The story of Galileo shows that relations between science and Church authority were sometimes tense, yet many scientists, including Kepler and Newton, held strong Christian faith.\n\nYour task: (1) Match each scientist to a discovery: Copernicus, Kepler, Newton. (2) Explain two causes of the Scientific Revolution. (3) Tell what the Galileo case shows.\n\nFlorida standards: SS.912.W.4.5, SS.912.W.4.6, SS.912.W.4.10.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.4.5, SS.912.W.4.6, SS.912.W.4.10", "script": "Welcome back. Listen, in the fifteen hundreds and sixteen hundreds, thinkers began to study nature with careful observation, measurement and experiment. We call it the Scientific Revolution. Many early scientists were devout believers who saw their work as studying God's creation. Psalm one eleven and two says, The works of the LORD are great, sought out of all them that have pleasure therein.\n\nNow watch this. Nicolaus Copernicus proposed in fifteen forty three that the earth and planets orbit the sun. Tycho Brahe made careful observations of the stars, and Johannes Kepler used them to show that planets move in ellipses. Galileo used the telescope to see moons around Jupiter and mountains on the moon. He defended the sun centered model, and in sixteen thirty three a Church court condemned him. Francis Bacon urged experiment and observation. Rene Descartes stressed reasoning and doubt. Andreas Vesalius studied the human body. William Harvey described the circulation of blood. And Isaac Newton described gravity and the laws of motion in sixteen eighty seven.\n\nLook at this. Why did it happen? The Renaissance brought new curiosity, printing spread discoveries, instruments like the telescope and microscope improved, and explorers brought new knowledge. The effects were the scientific method, new inventions, and a growing belief that evidence and reason can explain the world. Galileo's case shows that science and Church authority were sometimes in tension, yet many scientists, including Kepler and Newton, held strong Christian faith.\n\nYour task today. Match three scientists to their discoveries. Explain two causes of the Scientific Revolution. And tell what the Galileo case shows. Take the four question check.\n\nGod's works are worth seeking out. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 The Scientific Revolution$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Exploration, the Columbian Exchange and the Slave Trade$j$, $j${"readings": [{"title": "Exodus 21 (King James Version)", "url": "/portal/bible/Exodus/21"}], "body": "In the 1400s European nations sailed across the oceans. Motives are often summed up as God, gold and glory: spreading Christianity, finding trade and wealth, and winning fame and power. The Ottoman control of eastern trade routes also pushed Europeans to find sea routes. New technologies helped: the caravel, the compass, the astrolabe and better maps.\n\nPortugal led under Prince Henry the Navigator. Bartolomeu Dias rounded Africa's southern tip in 1488, and Vasco da Gama reached India in 1498. Spain backed Christopher Columbus, who reached the Caribbean in 1492. The Treaty of Tordesillas in 1494 divided new lands between Spain and Portugal. Ferdinand Magellan's expedition from 1519 to 1522 sailed around the world. Hernan Cortes defeated the Aztec in 1521 and Francisco Pizarro the Inca in 1533, helped by native allies, steel, horses and, above all, disease.\n\nThe Columbian Exchange moved plants, animals and diseases between the hemispheres. Europe gained potatoes, corn and tomatoes. The Americas gained horses, cattle, wheat and sugar cane. Smallpox and other diseases killed millions of native people.\n\nSpain governed colonies with settlers, missions and the encomienda system, forcing native labor. Bartolome de las Casas defended native rights. European nations also followed mercantilism, using colonies to build national wealth.\n\nThe demand for labor in mines and plantations led to the trans Atlantic slave trade. Over about 350 years, roughly twelve million Africans were taken, and many died during the Middle Passage. Slavery was a grievous evil. Exodus 21:16 says, And he that stealeth a man, and selleth him, or if he be found in his hand, he shall surely be put to death.\n\nYour task: (1) Match explorer to achievement: Dias, da Gama, Columbus, Magellan. (2) Name two items of the Columbian Exchange in each direction. (3) Explain two causes and two effects of the slave trade.\n\nFlorida standards: SS.912.W.4.11, SS.912.W.4.12, SS.912.W.4.13, SS.912.W.4.14, SS.912.W.4.15.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.4.11, SS.912.W.4.12, SS.912.W.4.13, SS.912.W.4.14, SS.912.W.4.15", "script": "Welcome back. Listen, in the fourteen hundreds European nations sailed across the oceans. Their motives are often summed up as God, gold and glory. They wanted to spread Christianity, find trade and wealth, and win fame and power. The Ottoman control of eastern trade routes also pushed them to find sea routes. New tools helped, the caravel, the compass, the astrolabe and better maps.\n\nNow watch this. Portugal led under Prince Henry the Navigator. Bartolomeu Dias rounded Africa's tip in fourteen eighty eight, and Vasco da Gama reached India in fourteen ninety eight. Spain backed Christopher Columbus, who reached the Caribbean in fourteen ninety two. The Treaty of Tordesillas in fourteen ninety four divided new lands between Spain and Portugal. Magellan's expedition, fifteen nineteen to fifteen twenty two, sailed around the world. Cortes defeated the Aztec in fifteen twenty one, and Pizarro the Inca in fifteen thirty three, helped by native allies, steel, horses and above all disease.\n\nLook at this. The Columbian Exchange moved plants, animals and diseases between the hemispheres. Europe gained potatoes, corn and tomatoes. The Americas gained horses, cattle, wheat and sugar cane. Smallpox and other diseases killed millions of native people. Spain used the encomienda system, forcing native labor, while Bartolome de las Casas defended native rights.\n\nHear this carefully. The demand for labor on plantations and in mines led to the trans Atlantic slave trade. Over about three hundred fifty years roughly twelve million Africans were taken, and many died in the Middle Passage. It was a grievous evil. Exodus twenty one and sixteen says, And he that stealeth a man, and selleth him, or if he be found in his hand, he shall surely be put to death.\n\nYour task today. Match explorers to achievements. Name two items of the Columbian Exchange each way. And explain two causes and two effects of the slave trade. Take the four question check.\n\nEvery person is made in the image of God. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Exploration, the Columbian Exchange and the Slave Trade$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: A Turning Point in the Modern World$j$, $j${"prompt": "Choose one of these movements: the Renaissance, the Reformation, the Scientific Revolution or the Age of Exploration. Write a report with complete sentences and labeled parts. Psalm 111:2 says, The works of the LORD are great, sought out of all them that have pleasure therein.\n\nPart 1: Explain the causes of your chosen movement and where and when it began.\nPart 2: Describe three key people and what each did.\nPart 3: Describe two effects of the movement on religion, government, learning or trade.\nPart 4: Explain one way the movement connects with each of the other three movements in this unit.\nPart 5: Describe one moral question that the movement raised (for example, indulgences, Galileo's trial, conquest of native peoples or the slave trade) and give a Biblical response using at least one KJV verse.\nPart 6: Make a short timeline of at least six dates related to the movement.", "rubric": "70 points. Causes, place and time: 10 points. Key people: 12 points. Effects: 10 points. Connections to other movements: 10 points. Moral question and Biblical response: 14 points. Timeline: 10 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: A Turning Point in the Modern World$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Faith, Discovery and Conscience$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains how the printing press helped both the Renaissance and the Reformation, (2) describes how faith and science can work together, using an example from this unit, (3) tells how Christians should respond when a nation profits from injustice such as slavery, and (4) connects your answer to Ephesians 2:8, which says, For by grace are ye saved through faith; and that not of yourselves: it is the gift of God. Then write a respectful reply of at least 40 words to another student, or answer this question: Why was the Columbian Exchange so important for both hemispheres? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Faith, Discovery and Conscience$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: The Renaissance: Rebirth of Learning and Art$j$, $j${"questions": [{"q": "The Renaissance began in:", "options": ["Italy", "Mali", "Mexico", "Japan"]}, {"q": "Humanism emphasized:", "options": ["Only military skill", "The study of literature, history and human achievement", "Rejecting all learning", "Closing universities"]}, {"q": "Who painted the Sistine Chapel ceiling?", "options": ["Machiavelli", "Raphael", "Michelangelo", "Gutenberg"]}, {"q": "Gutenberg's printing press with movable type helped to:", "options": ["Create gunpowder", "End the Renaissance", "Slow the spread of books", "Spread ideas and raise literacy"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Renaissance: Rebirth of Learning and Art$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,3}'::int[], array[$j$Rich Italian trade cities paid for art and learning.$j$,$j$Humanists revived classical learning.$j$,$j$Michelangelo painted it between 1508 and 1512.$j$,$j$Books became cheaper and more common.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Renaissance: Rebirth of Learning and Art$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: The Protestant and Catholic Reformations$j$, $j${"questions": [{"q": "Martin Luther posted his Ninety Five Theses in:", "options": ["1517", "1611", "1215", "1066"]}, {"q": "Luther taught that salvation is:", "options": ["Unavailable", "Given only to kings", "By faith in Christ alone", "Earned by money"]}, {"q": "The Act of Supremacy (1534) made the English king:", "options": ["A Jesuit", "A Catholic bishop", "Head of the Church of England", "The Holy Roman Emperor"]}, {"q": "The Council of Trent was part of the:", "options": ["Catholic Reformation", "Hundred Years War", "Crusades", "Enlightenment"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Protestant and Catholic Reformations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,0}'::int[], array[$j$He posted them in Wittenberg in 1517.$j$,$j$This is the doctrine of justification by faith.$j$,$j$Henry VIII broke with Rome.$j$,$j$Trent restated Catholic doctrine and corrected abuses.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Protestant and Catholic Reformations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: The Scientific Revolution$j$, $j${"questions": [{"q": "Copernicus proposed that:", "options": ["Stars are close", "Planets are square", "The sun orbits the earth", "The planets orbit the sun"]}, {"q": "Kepler showed that planets move in:", "options": ["Ellipses", "Perfect squares", "Spirals only", "Straight lines"]}, {"q": "Isaac Newton explained:", "options": ["The printing press", "Gravity and the laws of motion", "Steam power", "The compass"]}, {"q": "Galileo's telescope showed:", "options": ["Gutenberg's press", "Cells in blood", "Moons orbiting Jupiter", "The coast of America"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: The Scientific Revolution$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,2}'::int[], array[$j$His 1543 book advanced the sun centered model.$j$,$j$Kepler's laws describe elliptical orbits.$j$,$j$His 1687 Principia unified earth and sky.$j$,$j$He saw four moons around Jupiter.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: The Scientific Revolution$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Exploration, the Columbian Exchange and the Slave Trade$j$, $j${"questions": [{"q": "Who reached India by sea in 1498?", "options": ["Christopher Columbus", "Hernan Cortes", "Ferdinand Magellan", "Vasco da Gama"]}, {"q": "The Columbian Exchange was the movement of:", "options": ["Plants, animals and diseases between the hemispheres", "Only gold to Spain", "Only people to Africa", "Only ships to Japan"]}, {"q": "The main cause of massive native population loss was:", "options": ["Earthquakes", "Old World diseases such as smallpox", "Printing", "Trade in tea"]}, {"q": "The Middle Passage was the:", "options": ["Voyage that carried enslaved Africans across the Atlantic", "Silk route", "Pilgrim route to Mecca", "Road to Rome"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Exploration, the Columbian Exchange and the Slave Trade$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,0}'::int[], array[$j$Da Gama sailed around Africa to India.$j$,$j$It changed life on both sides of the Atlantic.$j$,$j$Native peoples lacked immunity.$j$,$j$Many died on the crossing.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Exploration, the Columbian Exchange and the Slave Trade$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: The Renaissance, the Reformation, the Scientific Revolution and the Age of Exploration$j$, $j${"questions": [{"q": "The Renaissance was marked by interest in:", "options": ["Feudal manors only", "Closing schools", "Ending trade", "Classical learning and human achievement"]}, {"q": "Leonardo da Vinci painted:", "options": ["Utopia", "David", "The School of Athens", "The Last Supper"]}, {"q": "The Reformation began when Luther:", "options": ["Crowned Charlemagne", "Signed the Magna Carta", "Sailed to America", "Posted the Ninety Five Theses"]}, {"q": "The Jesuits were founded by:", "options": ["Pizarro", "John Calvin", "Henry VIII", "Ignatius of Loyola"]}, {"q": "The scientific method stresses:", "options": ["Secret rules", "Guessing", "Observation and experiment", "Tradition alone"]}, {"q": "The Treaty of Tordesillas divided new lands between:", "options": ["England and France", "Rome and Persia", "Spain and Portugal", "Japan and China"]}, {"q": "Mercantilism was the idea that:", "options": ["Colonies should build the national wealth", "Trade harms nations", "Colonies should be independent", "Kings should not collect taxes"]}, {"q": "The trans Atlantic slave trade took roughly how many Africans?", "options": ["About one thousand", "About twelve million", "About one million only", "About one hundred"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Renaissance, the Reformation, the Scientific Revolution and the Age of Exploration$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,3,3,2,2,0,1}'::int[], array[$j$Humanism revived Greek and Roman learning.$j$,$j$Leonardo painted The Last Supper and Mona Lisa.$j$,$j$Luther challenged indulgences in 1517.$j$,$j$They became educators and missionaries.$j$,$j$Bacon and others urged experiment.$j$,$j$It was signed in 1494.$j$,$j$Mercantilist nations tried to export more than they imported.$j$,$j$Historians estimate about twelve million embarked.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Renaissance, the Reformation, the Scientific Revolution and the Age of Exploration$j$ on conflict (item_id) do nothing;
